import 'dart:convert';

import 'package:flutter/material.dart';

const _briskersLogoBase64 = r'''[...snip...]AAAAASUVORK5CYII=''';

class BriskersLogo extends StatelessWidget {
  const BriskersLogo({
    super.key,
    this.height = 40,
  });

  final double height;

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      base64Decode(_briskersLogoBase64),
      height: height,
      fit: BoxFit.contain,
      filterQuality: FilterQuality.high,
      gaplessPlayback: true,
    );
  }
}

class BriskersPageTitle extends StatelessWidget {
  const BriskersPageTitle({
    super.key,
    required this.title,
    this.logoHeight = 38,
  });

  final String title;
  final double logoHeight;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        BriskersLogo(height: logoHeight),
        const SizedBox(width: 10),
        Flexible(
          child: Text(
            title,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(fontWeight: FontWeight.w800),
          ),
        ),
      ],
    );
  }
}
